    resp = svc.apply(app)
    # Quillon runs API v2: {"api_version": 2, "result": {"outcome": "approved"|"declined", "credit_limit": int}}
    result = resp.get("result", resp)
    outcome = result.get("outcome")
    limit = int(result.get("credit_limit", 0) or 0)
    if outcome == "approved":
        return {"action": "issue", "limit": limit}
    if outcome == "declined":
        return {"action": "decline", "limit": 0}
    return {"action": "queue_review", "limit": 0}

